-- Review state per concept. Concept content lives in the repo (content/), not here.
CREATE TABLE cards (
  concept_id TEXT PRIMARY KEY,
  stage      INTEGER NOT NULL DEFAULT 0 CHECK (stage BETWEEN 0 AND 5),
  next       TEXT NOT NULL,                       -- YYYY-MM-DD, next review date
  status     TEXT NOT NULL CHECK (status IN ('new', 'ok', 'weak')),
  learned    TEXT,                                -- YYYY-MM-DD
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- One row per finished quiz. id is generated by the browser so retries don't duplicate rows.
CREATE TABLE quiz_log (
  id         TEXT PRIMARY KEY,
  date       TEXT NOT NULL,
  score      INTEGER NOT NULL,
  n          INTEGER NOT NULL,
  topics     TEXT NOT NULL,                       -- JSON array of topic names
  weak       TEXT NOT NULL,                       -- JSON array of concept ids answered wrong
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Raw notes captured in the app. The daily Claude routine turns them into concept files.
CREATE TABLE notes (
  id           TEXT PRIMARY KEY,
  text         TEXT NOT NULL,
  created_at   TEXT NOT NULL DEFAULT (datetime('now')),
  processed_at TEXT,
  concept      TEXT                               -- concept id the note became, if any
);
CREATE INDEX notes_unprocessed ON notes (processed_at);
